phase=0
start_t=0
def control(obs):
    global phase,start_t
    if phase==0:
        if obs.get('status')=='PULLING_FORWARD':
            phase=1
            start_t=obs.get('t',0)
        return (0.0,1.0,-23)
    if phase==1:
        if obs.get('t',0)-start_t < 3.0:
            return (0.0,1.0,-23)
        phase=2
    h=obs.get('hitch_deg',0.0)
    return (max(-8,min(8,1.0*h)),-0.25,-23)

