import math
def control(obs):
    h = obs.get('hitch_deg', 0.0)
    steer = max(-20.0, min(20.0, 1.25*h))
    pts = []
    for view in (obs.get('views') or {}).values():
        for b, d in view.get('walls', []):
            if d < 12:
                a = math.radians(b)
                pts.append((d*math.cos(a), d*math.sin(a)))
    left = [math.hypot(x, y) for x,y in pts if y > 0.2]
    right = [math.hypot(x, y) for x,y in pts if y < -0.2]
    if left and right:
        steer += max(-4.0, min(4.0, min(right)-min(left)))
    return (max(-24.0, min(24.0, steer)), -0.32, 0.0)

