    h = obs.get('hitch_deg', 0.0)
    steer = 0.9 * h
    cam = obs.get('views', {}).get('camera', {}) or {}
    rails = cam.get('walls', [])
    left = [d for b,d in rails if b > 90 or b < -170]
    right = [d for b,d in rails if -170 <= b < -90]
    if left and right:
        # Trailer rear should shift away from the nearer rail.
        err = min(right) - min(left)
        steer += max(-7.0, min(7.0, 1.2 * err))
    steer = max(-10.0, min(10.0, steer))
    return (steer, -0.45, -41.0)

