    cam = (obs.get('views', {}) or {}).get('camera', {}) or {}
    walls = cam.get('walls', [])
    left, right = [], []
    axis = cam.get('axis_deg', 177.0)
    for bearing, dist in walls:
        rel = (bearing - axis + 180.0) % 360.0 - 180.0
        if -100.0 <= rel <= 100.0:
            (left if rel > 0 else right).append(dist)
    bias = 0.0
    if left and right:
        bias = max(-2.0, min(2.0, 0.35 * (min(left) - min(right))))
    elif left:
        bias = 1.5
    elif right:
        bias = -1.5
    steer = max(-4.0, min(4.0, 0.8 * h + bias))
    return (steer, -0.12, -41.0)

